import numpy as np

def f(x, y, z, w):
    return y / (16*x**3 + 1) + z / (16*y**3 + 1) + w / (16*z**3 + 1) + x / (16*w**3 + 1)

min_val = 1.0
for _ in range(100000):
    # Randomly sample x, y, z, w that sum to 1
    r = np.random.rand(4)
    s = r.sum()
    x, y, z, w = r / s
    val = f(x, y, z, w)
    if val < min_val:
        min_val = val

print(min_val)
